/* Twistor — concept questions, GCSE physics (two per topic). Loaded on demand by concept.js.
   { q: question, o: options, a: index of the right option, w: feedback for each wrong option ('' for the right one), e: why the right one is right } */
(function () { const W = (window.WL = window.WL || {}); W.cq = Object.assign(W.cq || {}, {
'gcse-measurement': [
  { q: 'A runner completes one lap of a 400 m track and finishes exactly where she started. What are her distance travelled and her displacement?',
    o: ['Distance 400 m, displacement 400 m', 'Distance 0 m, displacement 400 m', 'Distance 400 m, displacement 0 m', 'Distance 0 m, displacement 0 m'],
    a: 2, w: ['Displacement is how far, and in what direction, she ends up from where she began. She ends where she began.', 'That is the wrong way round: she has certainly run 400 m of track.', '', 'Her feet covered 400 m of ground, so the distance is not zero.'],
    e: 'Distance is a scalar: the length of the path, 400 m. Displacement is a vector: the straight line from start to finish, which is zero for a full lap.' },
  { q: 'Forces of 3 N and 4 N act on an object at right angles to each other. What is the size of the resultant force?',
    o: ['7 N', '5 N', '1 N', '12 N'],
    a: 1, w: ['Sizes add only when the forces point the same way. At right angles they partly pull in different directions.', '', 'Subtracting is for forces in opposite directions.', 'Forces are never multiplied together to find a resultant.'],
    e: 'Forces are vectors. At right angles they combine by Pythagoras: √(3² + 4²) = 5 N.' } ],
'gcse-suvat': [
  { q: 'A ball is thrown straight up. At the top of its path, what are its velocity and its acceleration? (Ignore air resistance.)',
    o: ['Velocity zero and acceleration zero', 'Velocity zero and acceleration 9.8 m/s² downwards', 'Velocity 9.8 m/s downwards and acceleration zero', 'Velocity zero and acceleration 9.8 m/s² upwards'],
    a: 1, w: ['If the acceleration were zero at the top, the velocity would stay zero and the ball would hang there.', '', 'At the top the ball is not moving for an instant, so its velocity is zero.', 'Gravity pulls down the whole time, so the acceleration is downwards throughout the flight.'],
    e: 'Acceleration is the rate of change of velocity, not the velocity itself. Gravity changes the velocity by 9.8 m/s every second, at the top just as everywhere else.' },
  { q: 'A car moving forwards has an acceleration of −2 m/s². What does this mean?',
    o: ['The car is moving backwards', 'The car has stopped', 'The car travels 2 m less in each second', 'The car’s velocity falls by 2 m/s in each second'],
    a: 3, w: ['The sign of the acceleration says how the velocity is changing, not which way the car is moving.', 'A stopped car would have zero velocity; nothing here says the velocity has reached zero yet.', 'Acceleration is a change of velocity per second, not a change of distance.', ''],
    e: 'Acceleration = change in velocity ÷ time. Moving forwards with −2 m/s² means the car loses 2 m/s of speed every second.' } ],
'gcse-mass-weight': [
  { q: 'What is the weight of a 5 kg mass on the Earth, where g = 9.8 N/kg?',
    o: ['5 kg', '5 N', '49 N', '0.51 N'],
    a: 2, w: ['5 kg is its mass. Weight is a force and is measured in newtons.', 'The number of newtons is not the number of kilograms: each kilogram is pulled with 9.8 N.', '', 'That is 5 ÷ 9.8. Weight is mass × g, not mass ÷ g.'],
    e: 'Weight = mass × gravitational field strength = 5 × 9.8 = 49 N.' },
  { q: 'Which weighs more: a kilogram of lead or a kilogram of feathers?',
    o: ['The lead', 'The feathers', 'They weigh the same; the lead just takes up less space', 'It depends on how tightly the feathers are packed'],
    a: 2, w: ['Lead is denser, not heavier per kilogram. A kilogram is a kilogram.', 'The feathers take up more room, but their mass is the same 1 kg.', '', 'Packing changes the volume and so the density, but not the mass or the weight.'],
    e: 'Equal masses have equal weights. What differs is density: lead packs the same mass into a far smaller volume.' } ],
'gcse-forces': [
  { q: 'A book lies at rest on a table. Which statement describes the forces on the book?',
    o: ['Only its weight acts; the table is just in the way', 'Its weight acts down and the table pushes up with an equal force', 'No forces act, because it is at rest', 'Its weight acts down and the table pushes up with a smaller force'],
    a: 1, w: ['A table is not just an obstacle. Its surface is squashed very slightly and pushes back, like a stiff spring.', '', 'At rest means the forces are balanced, not that there are none. The book’s weight has not gone away.', 'With a smaller push up, the net force would be down and the book would sink into the table.'],
    e: 'The book is not accelerating, so the resultant force is zero: the upward push of the table (the normal contact force) equals the weight.' },
  { q: 'A constant resultant force acts on a trolley on a frictionless track. How does the trolley move?',
    o: ['At a constant speed', 'It speeds up at first and then settles at a steady speed', 'With constant acceleration: its speed keeps increasing', 'It depends on how long the force has been acting'],
    a: 2, w: ['Constant speed needs zero resultant force. A steady force gives a steady acceleration, not a steady speed.', 'That happens when friction or drag grows with speed. Here nothing opposes the force.', '', 'While the same resultant force acts, the acceleration is the same at every moment.'],
    e: 'F = ma: a constant resultant force gives a constant acceleration, so the speed rises by the same amount every second.' } ],
'gcse-moments': [
  { q: 'A uniform metre rule is pivoted at its 50 cm mark. A 2 N weight hangs at the 10 cm mark. What weight at the 70 cm mark balances it?',
    o: ['2 N', '1 N', '8 N', '4 N'],
    a: 3, w: ['Equal weights balance only at equal distances from the pivot. Here the distances are 40 cm and 20 cm.', 'A weight nearer the pivot must be bigger, not smaller.', 'The distance is halved, so the weight must double, not quadruple.', ''],
    e: 'Moments balance: 2 N × 40 cm = W × 20 cm, so W = 4 N. Distances are measured from the pivot, not from the end of the rule.' },
  { q: 'Why is a double-decker bus more stable with its passengers downstairs than upstairs?',
    o: ['It is lighter', 'Its centre of gravity is lower, so it can tilt further before toppling', 'The tyres grip the road better', 'The passengers downstairs can hold on more firmly'],
    a: 1, w: ['The total weight is the same wherever the passengers sit.', '', 'Grip stops sliding. Toppling is about where the weight acts compared with the base.', 'Holding on helps the passengers, not the balance of the bus.'],
    e: 'An object topples when the line of action of its weight falls outside its base. A lower centre of gravity lets the bus lean further before that happens.' } ],
'gcse-newton': [
  { q: 'A heavy lorry and a small car collide head-on. During the collision, how does the force of the lorry on the car compare with the force of the car on the lorry?',
    o: ['The lorry’s force on the car is bigger', 'The car’s force on the lorry is bigger', 'It depends on which was moving faster', 'The two forces are equal in size'],
    a: 3, w: ['The car is damaged more because its mass is smaller, so the same force changes its motion far more.', 'Neither can push harder than it is pushed.', 'Speed and mass change how big both forces are, but the two are always equal to each other.', ''],
    e: 'Newton’s third law: when two objects interact, they exert equal and opposite forces on each other. The effects differ because the masses differ.' },
  { q: 'A 2 kg trolley moving at 3 m/s collides with a stationary 1 kg trolley and they stick together. What is their speed afterwards?',
    o: ['3 m/s', '1.5 m/s', '2 m/s', '6 m/s'],
    a: 2, w: ['The same momentum is now shared by a larger mass, so the speed must fall.', 'Halving would be right only if the mass had doubled. It has gone from 2 kg to 3 kg.', '', '6 kg m/s is the momentum, not the speed.'],
    e: 'Momentum is conserved: 2 × 3 = 6 kg m/s before, and (2 + 1) × v after, so v = 2 m/s.' } ],
'gcse-energy': [
  { q: 'A car’s speed doubles. What happens to its kinetic energy?',
    o: ['It doubles', 'It becomes four times as large', 'It stays the same', 'It becomes eight times as large'],
    a: 1, w: ['Kinetic energy depends on the speed squared, not on the speed.', '', 'A faster car certainly has more kinetic energy.', 'The speed is squared, not cubed: 2² = 4.'],
    e: 'KE = ½mv². Doubling v multiplies v² by 4, which is why braking distance rises so steeply with speed.' },
  { q: 'A 1 kg ball and a 2 kg ball are dropped from the same height. Ignoring air resistance, compare them just before they land.',
    o: ['The heavier ball is moving faster', 'They have the same speed and the same kinetic energy', 'The lighter ball is moving faster', 'They have the same speed, but the heavier ball has twice the kinetic energy'],
    a: 3, w: ['Without air resistance all objects fall with the same acceleration, whatever their mass.', 'The speeds match, but kinetic energy also depends on mass.', 'Mass does not slow a falling object down or speed it up.', ''],
    e: 'Both gain speed at 9.8 m/s² and so land at the same speed. Since KE = ½mv², twice the mass at the same speed means twice the kinetic energy.' } ],
'gcse-work-power': [
  { q: 'You hold a heavy bag still at arm’s length for a minute. How much work do you do on the bag?',
    o: ['A lot, because it is tiring', 'None', 'Its weight multiplied by the time', 'Its weight multiplied by the length of your arm'],
    a: 1, w: ['Your muscles do use energy holding still, and it ends up warming you. But none is transferred to the bag.', '', 'Work is force × distance, not force × time.', 'The bag has not moved along the length of your arm.'],
    e: 'Work done = force × distance moved in the direction of the force. The bag does not move, so no work is done on it.' },
  { q: 'Asha and Ben have the same weight and climb the same stairs. Asha takes 10 s and Ben takes 20 s. Compare the work they do and their power.',
    o: ['Asha does more work', 'Ben does more work, because he takes longer', 'They do the same work with the same power', 'They do the same work, and Asha has twice the power'],
    a: 3, w: ['The work is weight × height, and both are the same for the two of them.', 'Taking longer does not add work. The same energy is transferred, just more slowly.', 'The work is the same, but power is how quickly it is done.', ''],
    e: 'Work = weight × height gained: the same for both. Power = work ÷ time, so doing it in half the time takes twice the power.' } ],
'gcse-resources': [
  { q: 'Which statement about nuclear power stations is correct?',
    o: ['They burn uranium and release carbon dioxide', 'They release no carbon dioxide while running, but leave radioactive waste and use a fuel that will run out', 'Uranium is renewable, because very little is needed', 'They can only supply electricity when demand is low'],
    a: 1, w: ['Nothing is burned. The energy comes from splitting nuclei (fission), which produces no carbon dioxide.', '', 'Using a fuel slowly does not make it renewable. Uranium ore is not replaced.', 'Nuclear stations run steadily day and night, whatever the demand.'],
    e: 'Fission releases energy without combustion, so there is no CO₂ from the reaction. The costs are radioactive waste and a finite supply of uranium.' },
  { q: 'Why can wind and solar power not easily supply a country on their own, all of the time?',
    o: ['They release too much carbon dioxide', 'The wind and the sunshine will run out', 'Their output depends on the weather and the time of day, not on when electricity is needed', 'They cannot be connected to the national grid'],
    a: 2, w: ['They release almost none while running.', 'They are renewable: the supply is not used up.', '', 'Wind and solar farms are connected to the grid already.'],
    e: 'Wind and solar are unreliable in the technical sense: their output cannot be turned up to match demand. That is why storage and back-up are needed alongside them.' } ],
'gcse-pressure': [
  { q: 'A diver goes from 10 m to 20 m below the surface of a lake. What happens to the pressure caused by the water alone?',
    o: ['It stays the same', 'It doubles', 'It rises slightly', 'It halves'],
    a: 1, w: ['Deeper means more water above, pressing down.', '', 'It rises in proportion to the depth, and the depth has doubled.', 'Pressure increases with depth. It does not fall.'],
    e: 'Pressure due to a liquid = height × density × g. Twice the depth of the same water gives twice the pressure.' },
  { q: 'A stiletto heel can dent a wooden floor that an elephant’s foot does not. Why?',
    o: ['The person presses down with a larger force than the elephant', 'The heel is made of a harder material', 'Pressure depends only on weight', 'Her much smaller weight acts on a far smaller area, so the pressure is larger'],
    a: 3, w: ['The elephant’s weight is far greater than hers.', 'Hardness is not the point: the same heel laid on its side would not dent the floor.', 'Pressure depends on the area as well as the force.', ''],
    e: 'Pressure = force ÷ area. A heel tip of about 1 cm² gives a pressure several times that under an elephant’s foot.' } ],
'gcse-particles': [
  { q: 'What causes the pressure of a gas on the walls of its container?',
    o: ['The particles colliding with the walls', 'The particles repelling one another', 'The weight of the gas pressing down', 'The particles expanding to fill the space'],
    a: 0, w: ['', 'In a gas the particles are too far apart to push on each other most of the time.', 'Weight would press only on the bottom. A gas presses equally on every wall.', 'The particles do not change size. They spread out because they are moving.'],
    e: 'Gas particles move fast in all directions. Each collision with a wall gives it a tiny push, and billions of collisions a second add up to a steady pressure.' },
  { q: 'A sealed, rigid container of gas is heated. Why does the pressure rise?',
    o: ['The particles get bigger', 'There are more particles', 'The particles move further apart', 'The particles move faster, hitting the walls harder and more often'],
    a: 3, w: ['Particles stay the same size at any temperature.', 'The container is sealed, so no particles are added.', 'The container is rigid: the volume, and so the spacing, cannot change.', ''],
    e: 'Temperature measures the average kinetic energy of the particles. Hotter particles move faster, so their collisions with the walls are harder and more frequent.' } ],
'gcse-expansion': [
  { q: 'A flat metal ring is heated. What happens to the hole in the middle?',
    o: ['It gets smaller, because the metal expands into it', 'It gets bigger', 'It stays the same size', 'It closes up completely'],
    a: 1, w: ['Every length in the metal grows, the distance round the edge of the hole included.', '', 'The hole is bounded by metal, and that boundary expands like the rest.', 'Expansion is a fraction of a percent, and in any case the hole grows.'],
    e: 'On heating, the ring expands as a photograph does when enlarged: every dimension grows, the diameter of the hole too. That is how a hot steel tyre is fitted on to a wheel.' },
  { q: 'A bimetallic strip is made of brass fixed to iron. Brass expands more than iron. When the strip is heated, it:',
    o: ['bends with the brass on the outside of the curve', 'bends with the brass on the inside of the curve', 'gets longer but stays straight', 'twists like a corkscrew'],
    a: 0, w: ['', 'The inside of a curve is the shorter side, and the brass has become the longer one.', 'The two metals are fixed together, so they cannot both keep their own new length while staying straight.', 'Both metals expand along the strip, so it bends in one plane.'],
    e: 'The brass becomes longer than the iron. The only way two joined strips can have different lengths is to curve, with the longer one on the outside.' } ],
'gcse-shc': [
  { q: 'Ice at 0 °C is heated steadily. What happens to its temperature while it is melting?',
    o: ['It rises steadily', 'It falls slightly', 'It stays at 0 °C until all the ice has melted', 'It jumps to room temperature'],
    a: 2, w: ['The energy supplied is not raising the temperature during melting. It is doing something else.', 'Energy is going in, so the temperature cannot fall.', '', 'The water formed is at 0 °C. It warms only after the ice has gone.'],
    e: 'During melting the energy supplied (the latent heat) breaks the bonds holding the particles in place. Their average kinetic energy, and so the temperature, does not change.' },
  { q: 'Equal masses of water and copper are given the same amount of energy. The copper’s temperature rises much more. Why?',
    o: ['Copper is a better conductor', 'Copper has a lower specific heat capacity', 'Copper is denser', 'The water loses the energy again at once'],
    a: 1, w: ['Conduction is about how fast energy spreads through a material, not how much its temperature rises.', '', 'The masses are equal, so density does not come into it.', 'The comparison assumes both keep the energy they are given.'],
    e: 'Specific heat capacity is the energy needed to raise 1 kg by 1 °C. Water needs about 4200 J, copper about 390 J, so the same energy heats copper roughly ten times as much.' } ],
'gcse-heat-transfer': [
  { q: 'Why does a woollen jumper keep you warm?',
    o: ['Wool produces heat', 'It keeps the cold out', 'Wool is a warm material', 'It traps air, a poor conductor, which slows the transfer of energy from your body'],
    a: 3, w: ['A jumper has no energy source. A jumper left on a chair is at room temperature.', 'There is no “cold” that travels. Energy flows from your warm body to the cooler surroundings.', 'No material is warm in itself. Wool feels warm because it slows the loss of your own body’s energy.', ''],
    e: 'You are the source of the warmth. The fibres trap pockets of air, and still air is a very poor conductor, so energy leaves your body more slowly.' },
  { q: 'Why is the heating element placed at the bottom of a kettle?',
    o: ['Because heat rises', 'Heated water expands, becomes less dense and rises, so all the water circulates past the element', 'The bottom is nearer the plug', 'Conduction is faster downwards'],
    a: 1, w: ['Heat is not a thing that rises. It is the hot, less dense water that rises.', '', 'The wiring could be run anywhere. The position is about how the water moves.', 'Conduction has no preferred direction, and water is a poor conductor anyway.'],
    e: 'Water warmed at the bottom expands and becomes less dense, so it rises and cooler water sinks to take its place. This convection current heats all the water.' } ],
'gcse-waves': [
  { q: 'The frequency of the waves on a string is doubled, and nothing else about the string changes. What happens?',
    o: ['The waves travel twice as fast', 'The wavelength halves and the speed stays the same', 'The wavelength doubles', 'The amplitude doubles'],
    a: 1, w: ['Wave speed is set by the string (its tension and mass), not by how fast the end is shaken.', '', 'More waves each second at the same speed must be closer together, not further apart.', 'Amplitude is how far the string moves, and it is separate from frequency.'],
    e: 'v = fλ, and v is fixed by the medium. Doubling f therefore halves λ.' },
  { q: 'In a longitudinal wave such as sound, how do the particles of the medium move?',
    o: ['They vibrate at right angles to the direction the wave travels', 'They travel along with the wave', 'They vibrate back and forth along the direction the wave travels', 'They move in circles'],
    a: 2, w: ['That describes a transverse wave, such as a ripple on water or light.', 'The wave moves on; the particles stay near where they were.', '', 'In sound the motion is back and forth along one line.'],
    e: 'In a longitudinal wave the vibrations are parallel to the direction of travel, making compressions and rarefactions. The particles oscillate about fixed positions.' } ],
'gcse-reflection-refraction': [
  { q: 'A ray of light passes from air into glass at an angle and bends towards the normal. Why?',
    o: ['The glass pulls the light towards it', 'Light travels more slowly in glass', 'Light speeds up in glass', 'The light loses energy as it enters'],
    a: 1, w: ['No force pulls on the light. The bending comes from a change of speed.', '', 'Speeding up would bend the ray away from the normal, as happens on the way out of the glass.', 'Very little energy is lost, and loss of energy would not turn the ray.'],
    e: 'Light travels more slowly in glass than in air. The side of the wavefront that enters first slows first, so the wave swings round towards the normal.' },
  { q: 'When can total internal reflection happen?',
    o: ['When light in air hits glass at a large angle', 'When light in a denser material, such as glass, meets a less dense one at more than the critical angle', 'At any boundary, if the light is bright enough', 'Only when the surface has a mirror coating'],
    a: 1, w: ['Going from air into glass, some light always gets through. It has to be travelling the other way.', '', 'Brightness makes no difference. The direction of travel and the angle decide it.', 'No coating is needed: the bare boundary reflects all the light. Optical fibres depend on this.'],
    e: 'Light leaving a denser material bends away from the normal. Beyond the critical angle no refracted ray is possible, and all of the light is reflected back inside.' } ],
'gcse-lenses': [
  { q: 'A converging lens forms a sharp image of a lamp on a screen. The top half of the lens is then covered with card. What happens to the image?',
    o: ['The top half of the image disappears', 'The bottom half of the image disappears', 'The whole image is still there, but dimmer', 'The image becomes blurred'],
    a: 2, w: ['Each point of the lamp sends light through every part of the lens, not just through one half.', 'The image is upside down, but covering half the lens removes neither half of it.', '', 'The uncovered half still focuses to the same points, so the image stays sharp.'],
    e: 'Light from every point of the object passes through all parts of the lens and meets at one image point. Half a lens still forms the whole image, with half the light.' },
  { q: 'An object is placed closer to a converging lens than its focal length. What kind of image is formed?',
    o: ['A real, upside-down image on a screen', 'A virtual, upright, magnified image', 'No image of any kind', 'A real image smaller than the object'],
    a: 1, w: ['Real images form only when the object is beyond the focal length.', '', 'There is an image: it is what you see when you look through a magnifying glass.', 'A real, smaller image needs the object more than two focal lengths away.'],
    e: 'Inside the focal length the rays leaving the lens still spread apart, as if from a larger object behind it. The eye sees an upright, magnified, virtual image: a magnifying glass.' } ],
'gcse-em-spectrum': [
  { q: 'Radio waves, visible light and X-rays travel through a vacuum. Which is fastest?',
    o: ['X-rays, because they carry the most energy', 'Radio waves, because they have the longest wavelength', 'Visible light', 'They all travel at the same speed'],
    a: 3, w: ['Energy and frequency do not change the speed in a vacuum.', 'Wavelength does not change the speed in a vacuum either.', 'Light is not special here: it is one part of the same family of waves.', ''],
    e: 'All electromagnetic waves travel at 3 × 10⁸ m/s in a vacuum. They differ in frequency and wavelength, not in speed.' },
  { q: 'What are radio waves?',
    o: ['Sound waves of very high frequency', 'Electromagnetic waves, like light but with a much longer wavelength', 'Vibrations of the air', 'Streams of electrons'],
    a: 1, w: ['A radio set turns the signal into sound, but the signal that travels to it is not sound.', '', 'Radio waves cross empty space, where there is no air to vibrate.', 'Electrons move in the aerial, but what travels between aerials is a wave, not a stream of particles.'],
    e: 'Radio waves belong to the electromagnetic spectrum, along with microwaves, light and X-rays. They need no medium and travel at the speed of light.' } ],
'gcse-sound': [
  { q: 'Through which of these does sound travel fastest?',
    o: ['Air', 'Water', 'Steel', 'A vacuum'],
    a: 2, w: ['Air is the slowest of the three materials: about 340 m/s.', 'Water carries sound at about 1500 m/s, faster than air but slower than steel.', '', 'Sound cannot travel through a vacuum at all.'],
    e: 'Sound is passed on by particles pushing their neighbours. In a stiff solid such as steel the particles are tightly bound, and the disturbance travels at about 5000 m/s.' },
  { q: 'What is ultrasound?',
    o: ['Sound that is too quiet to hear', 'Sound that travels faster than ordinary sound', 'Sound with a frequency above about 20 000 Hz, too high for humans to hear', 'A kind of electromagnetic wave'],
    a: 2, w: ['It is the frequency, not the loudness, that puts it beyond hearing.', 'It travels at the same speed as any other sound in the same material.', '', 'Ultrasound is a sound wave and needs a medium, unlike electromagnetic waves.'],
    e: 'Human hearing runs from about 20 Hz to 20 000 Hz. Sound above that range is ultrasound; it is used for scanning because it partly reflects at boundaries inside the body.' } ],
'gcse-magnetism': [
  { q: 'A straight wire carrying a current lies along the direction of a magnetic field (parallel to the field lines). What is the force on the wire?',
    o: ['The largest it can be', 'Zero', 'Half of the largest value', 'It depends only on the current'],
    a: 1, w: ['The force is largest when the wire is at right angles to the field.', '', 'The force falls smoothly to zero as the wire is turned parallel to the field.', 'The force depends on the angle between the wire and the field as well.'],
    e: 'The motor effect needs the current to cut across the field lines. A wire lying along the field feels no force; one at right angles feels the greatest force, F = BIL.' },
  { q: 'A wire in a magnetic field feels a force upwards. Which change reverses the direction of the force?',
    o: ['Reversing both the current and the field', 'Reversing either the current or the field, but not both', 'Increasing the current', 'Using a thicker wire'],
    a: 1, w: ['Two reversals cancel: the force ends up in its original direction.', '', 'A larger current makes the force bigger, in the same direction.', 'The thickness of the wire does not change the direction of the force.'],
    e: 'By Fleming’s left-hand rule the force direction depends on the directions of both the field and the current. Reverse one and the force reverses; reverse both and it does not.' } ],
'gcse-static': [
  { q: 'A plastic rod is rubbed with a cloth and becomes negatively charged. What has happened?',
    o: ['Protons have moved from the rod to the cloth', 'Rubbing has created new charge', 'The rod has been warmed', 'Electrons have moved from the cloth to the rod'],
    a: 3, w: ['Protons are held in the nuclei of atoms and do not move when things are rubbed.', 'Charge is never created. The cloth is left with a positive charge of the same size.', 'The warming is real, but it is not what makes the rod charged.', ''],
    e: 'Rubbing transfers electrons from one material to the other. The rod gains electrons and becomes negative; the cloth loses the same number and becomes positive.' },
  { q: 'A negatively charged balloon sticks to a wall that has no overall charge. Why?',
    o: ['The wall must secretly have a positive charge overall', 'The balloon has become magnetic', 'The balloon repels electrons in the wall’s surface slightly, leaving the surface nearest to it positive, and it is attracted to that', 'Charged objects stick to anything, like glue'],
    a: 2, w: ['The wall stays neutral overall. Its charges only shift a little.', 'Static charge is not magnetism: a charged balloon does not pick up iron filings.', '', 'The sticking is an electric force with a cause: the nearby surface charge is of the opposite sign.'],
    e: 'The balloon’s charge pushes electrons in the wall’s surface slightly away. The positive charge left nearer the balloon attracts it more strongly than the more distant negative charge repels it.' } ],
'gcse-current-pd': [
  { q: 'Electrons in a wire drift along at less than a millimetre a second, yet a lamp lights the instant you press the switch. Why?',
    o: ['The electrons from the switch travel to the lamp at the speed of light', 'The push from the supply is felt round the whole circuit almost at once, so electrons everywhere start to drift together', 'The lamp stores light, ready for when it is needed', 'The first electrons move fast and the later ones slowly'],
    a: 1, w: ['No electron makes the journey that quickly. It could take hours for one to drift from the switch to the lamp.', '', 'A lamp stores no light. It emits light only while a current flows in it.', 'All the free electrons in the wire drift at about the same slow speed.'],
    e: 'The wires are already full of free electrons. Closing the switch sets up an electric field through the whole circuit at close to the speed of light, and electrons in the lamp start moving at once.' },
  { q: 'A voltmeter connected across a lamp reads 6 V. What does that tell you?',
    o: ['A current of 6 A flows through the lamp', 'The lamp contains 6 coulombs of charge', 'The resistance of the lamp is 6 Ω', 'Each coulomb of charge that passes through the lamp transfers 6 J of energy'],
    a: 3, w: ['Current is measured in amperes by an ammeter in series. A voltmeter measures something different.', 'The charge passing depends on the current and the time, not on the voltage alone.', 'Resistance is voltage ÷ current, and we have not been told the current.', ''],
    e: 'Potential difference is the energy transferred per unit charge: 1 V = 1 J/C. A reading of 6 V means 6 J for every coulomb passing through the lamp.' } ],
'gcse-circuits': [
  { q: 'A resistor is connected to a battery. A second resistor is then added in parallel with the first. What happens to the total resistance of the circuit?',
    o: ['It increases, because there are more resistors', 'It decreases', 'It stays the same', 'It doubles'],
    a: 1, w: ['More resistors in series would do that. In parallel, the second resistor is an extra path for the charge.', '', 'A new path lets more current flow from the same battery, so the total resistance has changed.', 'Doubling happens when an equal resistor is added in series.'],
    e: 'A parallel branch gives the current another route, so more current flows for the same voltage. The total resistance is always less than that of the smallest branch.' },
  { q: 'A 2 Ω resistor and a 4 Ω resistor are connected in series across a 12 V battery. What is the potential difference across the 4 Ω resistor?',
    o: ['6 V', '4 V', '8 V', '12 V'],
    a: 2, w: ['The voltage is shared equally only if the resistors are equal.', '4 V is across the 2 Ω resistor. The larger resistor takes the larger share.', '', 'The two resistors share the 12 V between them.'],
    e: 'The same current flows through both: I = 12 ÷ (2 + 4) = 2 A. Across the 4 Ω resistor V = IR = 2 × 4 = 8 V. In series the voltage divides in the ratio of the resistances.' } ],
'gcse-power-cost': [
  { q: 'An electricity bill charges for each kilowatt-hour (kWh) used. What is a kilowatt-hour a unit of?',
    o: ['Power', 'Current', 'Energy', 'Time'],
    a: 2, w: ['The kilowatt is the unit of power. Multiplying by hours turns it into something else.', 'Current is measured in amperes.', '', 'The hour is the unit of time. A kilowatt-hour is a power multiplied by a time.'],
    e: 'Energy = power × time. One kilowatt-hour is the energy transferred by a 1 kW appliance in 1 hour: 3.6 million joules.' },
  { q: 'A 2 kW heater runs for 3 hours. A 100 W lamp runs for 30 hours. Which transfers more energy?',
    o: ['The lamp, because it is on for ten times as long', 'The heater', 'They transfer the same', 'It cannot be worked out without the voltage'],
    a: 1, w: ['The lamp is on ten times longer, but the heater’s power is twenty times greater.', '', 'Work out both: 6 kWh for the heater and 3 kWh for the lamp.', 'Energy is power × time. The voltage is not needed.'],
    e: 'Heater: 2 kW × 3 h = 6 kWh. Lamp: 0.1 kW × 30 h = 3 kWh. The heater transfers twice as much.' } ],
'gcse-series-parallel': [
  { q: 'A battery, lamp A, a variable resistor and lamp B are connected in series, in that order. The resistance of the variable resistor is increased. What happens to the lamps?',
    o: ['Only lamp B, after the resistor, gets dimmer', 'Only lamp A, before the resistor, gets dimmer', 'Both lamps get dimmer by the same amount', 'Neither lamp changes'],
    a: 2, w: ['Current is not something that “arrives” at one component before another. A change anywhere in a series loop changes the current everywhere.', 'The position of a component in a series loop makes no difference to the current through it.', '', 'A larger total resistance means a smaller current from the same battery.'],
    e: 'In a series circuit the current is the same at every point. Increasing the resistance reduces that one current, so both lamps dim equally, wherever they sit.' },
  { q: 'Why are the lights in a house wired in parallel and not in series?',
    o: ['Each lamp gets the full mains voltage and can be switched on and off on its own', 'Parallel circuits use less current', 'It needs less wire', 'In series the lamps would be too bright'],
    a: 0, w: ['', 'Each added lamp draws its own current, so the total current is larger in parallel.', 'Parallel wiring needs more wire, not less.', 'In series the lamps would share the voltage and be dimmer, and one failed lamp would put them all out.'],
    e: 'In parallel every lamp is connected directly across the supply, so each has the full voltage, and switching or losing one does not affect the others.' } ],
'gcse-safety': [
  { q: 'How does a fuse protect a circuit?',
    o: ['It lowers the voltage to a safe value', 'It stores spare current', 'It melts and breaks the circuit if the current becomes too large', 'It stops the current from becoming too small'],
    a: 2, w: ['A fuse does not change the voltage. It is a thin wire that simply carries the current.', 'Current cannot be stored.', '', 'A small current is harmless. The danger is a large current overheating the wiring.'],
    e: 'A fuse is a thin wire chosen to melt at a little more than the normal current. If a fault makes the current too large, the fuse melts first and cuts off the supply before the cable overheats.' },
  { q: 'A bird sits on a single high-voltage power line and is not harmed. Why?',
    o: ['Its feet are good insulators', 'Both of its feet are at almost the same potential, so there is almost no potential difference across it', 'The cable is covered with insulation', 'Birds are too small to conduct electricity'],
    a: 1, w: ['A bird’s feet conduct. It is the lack of a voltage across them that keeps it safe.', '', 'Overhead power lines are bare metal.', 'Size is not the reason: a bird touching two lines at different voltages would be killed.'],
    e: 'Current flows through something only if there is a potential difference across it. Both feet are on the same wire, at the same potential, so almost no current flows through the bird.' } ],
'gcse-electromagnets': [
  { q: 'A compass needle near a wire swings round when a current is switched on in the wire. What does this show?',
    o: ['The wire has become electrically charged', 'A current produces a magnetic field around it', 'The compass is attracted to copper', 'The wire has warmed the air near the needle'],
    a: 1, w: ['The wire stays neutral overall: charge flows through it, but does not build up on it.', '', 'Copper is not magnetic, and the needle ignores the wire when no current flows.', 'Warm air would not turn the needle to a definite direction that reverses when the current reverses.'],
    e: 'An electric current always has a magnetic field around it, in circles round the wire. This is the basis of every electromagnet and motor.' },
  { q: 'Which change does NOT make an electromagnet stronger?',
    o: ['Adding more turns to the coil', 'Increasing the current', 'Putting an iron core inside the coil', 'Reversing the direction of the current'],
    a: 3, w: ['More turns add their fields together, so the magnet is stronger.', 'A larger current gives a stronger field.', 'An iron core becomes magnetised and greatly strengthens the field.', ''],
    e: 'Reversing the current swaps the north and south poles but leaves the strength unchanged. Strength depends on the current, the number of turns and the core.' } ],
'gcse-motor': [
  { q: 'What does the split-ring commutator do in a d.c. motor?',
    o: ['It reverses the current in the coil every half turn, so the coil keeps turning the same way', 'It increases the current in the coil', 'It changes the direct current into alternating current for the supply', 'It stops the coil from overheating'],
    a: 0, w: ['', 'It does not change the size of the current, only its direction through the coil.', 'The supply stays d.c. Only the connection to the coil is swapped over.', 'It has nothing to do with cooling.'],
    e: 'Without it, the forces on the coil would reverse after half a turn and push it back. Swapping the current every half turn keeps the turning effect in one direction.' },
  { q: 'A d.c. motor is turning. Both the battery connections and the magnets are then reversed. What does the motor do?',
    o: ['It turns in the opposite direction', 'It turns in the same direction as before', 'It stops', 'It turns twice as fast'],
    a: 1, w: ['Reversing one of them would do that. Reversing both gives two reversals, which cancel.', '', 'The force on the coil is the same size as before.', 'Nothing has been made stronger, so the speed is unchanged.'],
    e: 'The force depends on the direction of both the current and the field. Reversing both leaves the force, and so the rotation, in its original direction.' } ],
'gcse-induction': [
  { q: 'A strong magnet rests, not moving, inside a coil connected to a sensitive ammeter. What does the ammeter read?',
    o: ['A large steady current, because the magnet is strong', 'A small steady current', 'Zero', 'A current that keeps changing direction'],
    a: 2, w: ['The strength of the field does not matter if it is not changing.', 'No change means no induced voltage at all, not a small one.', '', 'An alternating current needs the field through the coil to keep changing.'],
    e: 'A voltage is induced only while the magnetic field through the coil is changing. A stationary magnet, however strong, induces nothing.' },
  { q: 'The magnet is now pushed into the coil. Pushing it in faster makes the induced voltage:',
    o: ['larger', 'smaller', 'the same', 'reverse its direction'],
    a: 0, w: ['', 'Faster movement means a faster change of field, which induces more, not less.', 'The size of the induced voltage depends on how quickly the field changes.', 'The direction reverses only if the magnet is pulled out or turned round.'],
    e: 'The induced voltage is proportional to the rate at which the magnetic field through the coil changes. Moving the magnet faster changes it more quickly.' } ],
'gcse-transformer': [
  { q: 'The primary coil of a step-up transformer is connected to a battery (steady direct current). After the first instant, what is the output voltage?',
    o: ['Stepped up, as usual', 'The same as the battery voltage', 'Half of the battery voltage', 'Zero'],
    a: 3, w: ['Stepping up needs a changing field, and a steady current gives a steady field.', 'There is no connection between the coils except the magnetic field, and that field is not changing.', 'No voltage at all is induced by a steady field.', ''],
    e: 'A transformer works by induction: a changing current in the primary gives a changing magnetic field in the core, which induces a voltage in the secondary. Steady d.c. gives a steady field and no output.' },
  { q: 'Why is electricity sent along the national grid at very high voltage?',
    o: ['High-voltage electricity travels faster', 'For the same power the current is smaller, so less energy is wasted heating the cables', 'High voltage carries more power', 'It is safer'],
    a: 1, w: ['The speed is the same at any voltage.', '', 'The power sent is the same. Raising the voltage lowers the current by the same factor.', 'It is more dangerous, which is why the cables are high above the ground.'],
    e: 'Power = voltage × current, so a higher voltage delivers the same power with a smaller current. The heating loss in the cables is I²R, so a tenth of the current wastes a hundredth of the energy.' } ],
'gcse-atom': [
  { q: 'In Rutherford’s experiment, most alpha particles went straight through a thin gold foil. What did this show?',
    o: ['Atoms are mostly empty space', 'Atoms are solid spheres', 'Alpha particles are too small to hit anything', 'Gold is a soft metal'],
    a: 0, w: ['', 'A solid atom would have stopped or deflected nearly all of them.', 'A few alpha particles bounced back, so there is something small and massive to hit.', 'Softness has nothing to do with it. The result is about the structure inside each atom.'],
    e: 'Nearly all the alpha particles passed through undeflected, so most of an atom is empty. The very few that bounced back showed a tiny, dense, positive nucleus at the centre.' },
  { q: 'What is true of isotopes of the same element?',
    o: ['They have different numbers of protons', 'They have the same number of protons but different numbers of neutrons', 'They have different numbers of electrons, so they are charged', 'They have exactly the same mass'],
    a: 1, w: ['The number of protons fixes the element. Change it and you have a different element.', '', 'Those are ions. Isotopes are neutral atoms that differ in the nucleus.', 'Extra neutrons add mass, so isotopes differ in mass.'],
    e: 'Isotopes are atoms of one element (same proton number) with different numbers of neutrons, and so different mass numbers, such as carbon-12 and carbon-14.' } ],
'gcse-radiation': [
  { q: 'Fruit is exposed to gamma radiation to kill the bacteria on it. Is the fruit radioactive afterwards?',
    o: ['Yes, permanently', 'Yes, for one half-life', 'No', 'Only on its surface'],
    a: 2, w: ['Being exposed to radiation does not turn the atoms of the fruit into radioactive ones.', 'A half-life belongs to a radioactive material. No such material is on or in the fruit.', '', 'Nothing radioactive has been put on the surface. The radiation passed through and has gone.'],
    e: 'Irradiation means exposing an object to radiation from a source outside it. The object becomes radioactive only if radioactive material gets on or into it, which is contamination.' },
  { q: 'Alpha radiation is stopped by a sheet of paper, while gamma radiation passes through. Why is alpha the least penetrating?',
    o: ['It has the least energy', 'It is the most strongly ionising, so it loses its energy in a very short distance', 'It travels in curved paths', 'It is the lightest type of radiation'],
    a: 1, w: ['Alpha particles carry a lot of energy. They simply give it up very quickly.', '', 'Alpha particles travel in nearly straight lines.', 'An alpha particle is the heaviest of the three: two protons and two neutrons.'],
    e: 'An alpha particle is large and has a charge of +2, so it ionises many atoms along its path, losing energy at each one. It is stopped within a few centimetres of air or a sheet of paper.' } ],
'gcse-radioactivity': [
  { q: 'A radioactive sample has a half-life of 2 days. What fraction of the original radioactive nuclei is left after 4 days?',
    o: ['None', 'One half', 'One quarter', 'One eighth'],
    a: 2, w: ['Two half-lives do not finish it off. Each half-life removes half of what is left, not half of the original.', 'One half is what remains after 2 days.', '', 'One eighth is what remains after three half-lives, 6 days.'],
    e: 'After each half-life, half of the remaining nuclei have decayed: one half after 2 days, then half of that, one quarter, after 4 days.' },
  { q: 'Can physicists predict the moment when one particular unstable nucleus will decay?',
    o: ['Yes: exactly one half-life after it formed', 'Yes, if its temperature is known', 'No: decay is random, and only the behaviour of large numbers of nuclei can be predicted', 'Yes: the oldest nuclei always decay first'],
    a: 2, w: ['The half-life describes a large collection. A single nucleus may decay in the next second or in a thousand years.', 'Temperature and pressure have no effect on radioactive decay.', '', 'A nucleus does not age. Its chance of decaying in the next second is the same however long it has existed.'],
    e: 'Radioactive decay is random and spontaneous. Each nucleus has a fixed chance of decaying in each second, so only the average behaviour of many nuclei, the half-life, is predictable.' } ],
'gcse-earth-moon': [
  { q: 'Why is it warmer in summer than in winter?',
    o: ['The Earth is closer to the Sun in summer', 'The Earth’s axis is tilted, so in summer sunlight strikes more directly and the days are longer', 'The Sun gives out more energy in summer', 'There are fewer clouds in summer'],
    a: 1, w: ['The Earth is in fact closest to the Sun in early January. And it is summer in Australia when it is winter in Britain.', '', 'The Sun’s output is steady through the year.', 'Cloud changes the weather from day to day, not the seasons.'],
    e: 'The Earth’s axis is tilted at about 23°. The half of the Earth tilted towards the Sun gets sunlight at a steeper angle and for more hours each day.' },
  { q: 'What causes the phases of the Moon?',
    o: ['The shadow of the Earth falling on the Moon', 'Clouds covering part of the Moon', 'The Moon giving out more light at some times than at others', 'We see different amounts of the sunlit half of the Moon as it orbits the Earth'],
    a: 3, w: ['The Earth’s shadow reaches the Moon only during an eclipse of the Moon, a few times a year at most.', 'The phases repeat on an exact timetable of about 29.5 days, which clouds could not do.', 'The Moon gives out no light of its own. It reflects sunlight.', ''],
    e: 'Half of the Moon is always lit by the Sun. As the Moon orbits the Earth each month, we see more or less of that lit half.' } ],
'gcse-solar-system': [
  { q: 'A planet moves round the Sun in a circle at a constant speed. Is it accelerating?',
    o: ['No, because its speed is constant', 'Yes, because its direction of motion keeps changing', 'Only if it is getting closer to the Sun', 'No, because there is no force on it'],
    a: 1, w: ['Acceleration is a change of velocity, and velocity includes direction.', '', 'Even at a fixed distance its velocity is changing direction all the time.', 'There is a force on it: the Sun’s gravity. Without one it would fly off in a straight line.'],
    e: 'Velocity is a vector. A planet in a circular orbit keeps changing direction, so it is accelerating, towards the Sun, even at constant speed.' },
  { q: 'What keeps a planet in orbit round the Sun?',
    o: ['A force pushing the planet forwards along its orbit', 'The Sun’s gravity pulling it inwards while it moves sideways', 'An outward force balancing gravity exactly', 'Nothing: there are no forces in space'],
    a: 1, w: ['No forward push is needed. With nothing to slow it, the planet keeps the speed it has.', '', 'If the forces on it balanced, the planet would travel in a straight line, not a curve.', 'Gravity acts across space. It is the one force that matters here.'],
    e: 'The only force is gravity, directed towards the Sun. It bends the planet’s path into an orbit without changing its speed; the sideways motion is why the planet never falls in.' } ],
'gcse-stars': [
  { q: 'Where does the Sun’s energy come from?',
    o: ['Burning hydrogen gas in oxygen', 'Nuclear fission of uranium', 'Nuclear fusion of hydrogen nuclei into helium', 'Heat left over from when it formed'],
    a: 2, w: ['The Sun is not on fire. Burning is a chemical reaction and would have lasted only a few thousand years.', 'Fission splits heavy nuclei. The Sun is made almost entirely of hydrogen and helium.', '', 'Left-over heat would have run out long ago. Fusion has kept the Sun shining for 4.6 billion years.'],
    e: 'In the Sun’s core the temperature and pressure are high enough to fuse hydrogen nuclei into helium. A little mass is lost in each fusion and released as energy.' },
  { q: 'What will the Sun become at the end of its life?',
    o: ['A black hole', 'A red giant and then a white dwarf', 'A supernova and then a neutron star', 'It will keep shining as it does now for ever'],
    a: 1, w: ['Only stars many times more massive than the Sun end as black holes.', '', 'A supernova needs a star at least eight times as massive as the Sun.', 'Its hydrogen fuel is limited: about another 5 billion years’ worth.'],
    e: 'A star of the Sun’s mass swells into a red giant when the hydrogen in its core runs out, then sheds its outer layers and leaves a small, hot white dwarf that slowly cools.' } ],
'gcse-orbits': [
  { q: 'The light from distant galaxies is red-shifted. What does this tell us?',
    o: ['The galaxies are made of red stars', 'The galaxies are moving away from us', 'The galaxies are moving towards us', 'The galaxies are very old and cool'],
    a: 1, w: ['Red-shift is not about colour as such: every line in the spectrum is moved to a longer wavelength by the same fraction.', '', 'Motion towards us would shift the light to shorter wavelengths: a blue-shift.', 'Temperature changes which colours are brightest, but it does not move the spectral lines.'],
    e: 'Light from a receding source is stretched to longer wavelengths. The further away a galaxy is, the larger its red-shift, which is the evidence that the universe is expanding.' },
  { q: 'What does the Big Bang theory say about how the universe began?',
    o: ['An explosion at one point threw matter out into empty space that was already there', 'The universe has always existed much as it is now', 'The universe began very hot and dense, and space itself has been expanding ever since', 'The universe began when the first star exploded'],
    a: 2, w: ['There was no surrounding space to explode into. It is space itself that expands, everywhere at once, with no centre.', 'That is the Steady State idea, which cannot explain the cosmic microwave background.', '', 'Stars formed hundreds of millions of years after the beginning.'],
    e: 'About 13.8 billion years ago all of the universe was extremely hot and dense. Space has expanded since then, carrying the galaxies apart; red-shift and the cosmic microwave background are the evidence.' } ],
}); })();
